package com.anb.root;
import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.concurrent.*;import android.content.*;
public class EngineIntegrationTest {
 static File state,assets;static int index;
 static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);}
 static RecoveryEngine fresh()throws Exception {Field f=RecoveryEngine.class.getDeclaredField("instance");f.setAccessible(true);f.set(null,null);ShizukuShell.reset();CommandRunner.denied=CommandRunner.dropModule=CommandRunner.dropEnforcement=CommandRunner.badProtection=false;android.os.Build.DISPLAY=DeviceProfile.DISPLAY;Context c=new Context(new File(state,"case-"+(index++)),assets);c.getSharedPreferences("setup",0).edit().putBoolean("completed",true).commit();return RecoveryEngine.get(c);}
 static void run(RecoveryEngine e,boolean mayLaunch)throws Exception {CountDownLatch done=new CountDownLatch(1);check(e.start(s->{},done::countDown,mayLaunch),"request accepted");check(done.await(8,TimeUnit.SECONDS),"task completed");check(!e.isBusy(),"task released");}
 static void checkEnvironment(RecoveryEngine e)throws Exception {
  e.checkEnvironment();long end=System.nanoTime()+3_000_000_000L;
  while(e.isBusy()&&System.nanoTime()<end)Thread.sleep(10);
  check(!e.isBusy(),"environment task completed");
 }
 public static void main(String[] args)throws Exception {
  assets=new File(args[0]);state=Files.createTempDirectory(new File(args[1]).toPath(),"engine-").toFile();String old=System.getProperty("os.version");System.setProperty("os.version",DeviceProfile.KERNEL);
  try {
   RecoveryEngine e=fresh();run(e,false);check(e.failureKind==FailureText.Kind.PREPARE&&ShizukuShell.launches==0,"verification-only never starts a new chain");
   e=fresh();android.os.Build.DISPLAY="other firmware";run(e,true);check(e.failureKind==FailureText.Kind.COMPATIBILITY&&ShizukuShell.commands.isEmpty(),"wrong firmware denied before shell work");
   e=fresh();ShizukuShell.uptime=40;run(e,true);check(e.failureKind==FailureText.Kind.BOOT_WAIT&&ShizukuShell.launches==0,"boot wait before any launch");ShizukuShell.uptime=120;run(e,true);check(ShizukuShell.launches==1,"boot wait retry can start once");run(e,true);check(ShizukuShell.launches==1,"existing attempt never launches twice");
   e=fresh();ShizukuShell.locked=true;run(e,true);check(e.failureKind==FailureText.Kind.REBOOT_REQUIRED&&ShizukuShell.launches==0,"lost state plus boot lock denies rerun");
   e=fresh();ShizukuShell.module=true;ShizukuShell.permissive=true;run(e,false);check(e.failureKind==FailureText.Kind.SECURITY_NOT_RESTORED&&ShizukuShell.launches==0,"security failure typed and no launch");
   e=fresh();ShizukuShell.module=true;String dir="/data/local/tmp/anb_root_runs/run_88_1000_0123456789abcdef0123456789abcdef";e.context.getSharedPreferences("run",0).edit().putString("boot","88").putString("dir",dir).commit();run(e,false);check(e.phase==RecoveryEngine.Phase.SUCCESS&&dir.equals(e.context.getSharedPreferences("run",0).getString("dir","")),"verification retains the owned run directory");
   e=fresh();ShizukuShell.module=true;ShizukuShell.locked=true;run(e,false);check(e.failureKind==FailureText.Kind.REBOOT_REQUIRED,"loaded orphaned module cannot bypass boot lock");
   e=fresh();ShizukuShell.module=true;e.context.getSharedPreferences("run",0).edit().putString("boot","88").putString("dir","/invalid").commit();run(e,false);check(e.failureKind==FailureText.Kind.REBOOT_REQUIRED,"loaded module cannot bypass corrupt run directory");
   e=fresh();ShizukuShell.module=true;new File(e.context.getExternalFilesDir(null),"environment-shizuku.txt").mkdirs();new File(e.context.getExternalFilesDir(null),"verification.txt").mkdirs();run(e,false);check(e.phase==RecoveryEngine.Phase.SUCCESS&&e.logs().contains("辅助诊断保存未完成"),"diagnostic storage failure cannot overturn verified root");
   checkEnvironment(e);check(e.phase==RecoveryEngine.Phase.SUCCESS,"environment check preserves same-boot verified result");
   e=fresh();ShizukuShell.module=true;CommandRunner.denied=true;run(e,false);check(e.phase==RecoveryEngine.Phase.WAIT_AUTH,"denied su offers authorization");checkEnvironment(e);check(e.phase==RecoveryEngine.Phase.WAIT_AUTH,"environment check preserves authorization guidance");
   e=fresh();ShizukuShell.module=true;CommandRunner.denied=CommandRunner.dropEnforcement=true;run(e,false);check(e.failureKind==FailureText.Kind.SECURITY_NOT_RESTORED,"su failure with lost enforcement is not authorization");checkEnvironment(e);check(e.failureKind==FailureText.Kind.SECURITY_NOT_RESTORED&&e.phase==RecoveryEngine.Phase.FAILED,"environment check preserves same-boot security failure");
   e=fresh();ShizukuShell.module=true;CommandRunner.denied=CommandRunner.dropModule=true;run(e,false);check(e.failureKind==FailureText.Kind.PREPARE&&!e.modulePresent,"su failure with lost module requests recheck");
   e=fresh();ShizukuShell.module=true;CommandRunner.badProtection=true;run(e,false);check(e.failureKind==FailureText.Kind.SECURITY_NOT_RESTORED,"root id without restored protection is not success");
   e=fresh();ShizukuShell.module=true;ShizukuShell.badCleanup=true;e.context.getSharedPreferences("run",0).edit().putString("boot","88").putString("dir",dir).commit();run(e,false);check(e.failureKind==FailureText.Kind.SECURITY_NOT_RESTORED,"finished loader without cleanup fails safely");
   e=fresh();ShizukuShell.module=true;ShizukuShell.badStages=true;e.context.getSharedPreferences("run",0).edit().putString("boot","88").putString("dir",dir).commit();run(e,false);check(e.failureKind==FailureText.Kind.REBOOT_REQUIRED,"finished loader without userspace bringup fails safely");
   e=fresh();e.context.getSharedPreferences("recovery_options",0).edit().putString("allow_shell","corrupt").commit();check(!e.allowShellSelected()&&!e.allowShellSelected(),"corrupt option getter safely defaults off for page rendering");check(e.logs().split("恢复选项记录格式异常",-1).length==2,"corrupt option warning recorded once");ShizukuShell.module=true;run(e,false);check(e.phase==RecoveryEngine.Phase.SUCCESS&&!e.isBusy(),"safe default option does not prevent existing root verification");
   e=fresh();e.context.getSharedPreferences("setup",0).edit().putString("completed","corrupt").commit();check(!e.setupCompleted()&&!e.setupCompleted(),"corrupt setup getter safely requests first preparation");check(e.logs().split("首次准备记录格式异常",-1).length==2,"corrupt setup warning recorded once");run(e,true);check(e.failureKind==FailureText.Kind.PREPARE&&ShizukuShell.launches==0,"corrupt setup cannot launch payload");e.context.getSharedPreferences("setup",0).edit().putBoolean("completed",true).commit();check(e.setupCompleted(),"first preparation can repair malformed saved type");
   for(String corruptKey:new String[]{"boot","dir"}){
    e=fresh();e.context.getSharedPreferences("run",0).edit().putBoolean(corruptKey,true).commit();ShizukuShell.module=true;run(e,true);check(e.failureKind==FailureText.Kind.REBOOT_REQUIRED&&ShizukuShell.launches==0,"corrupt run type cannot bypass loaded module: "+corruptKey);check(e.message.contains("清除 ANB Root 应用数据")&&e.message.contains("仅重启不会修复"),"corrupt run type gives persistent repair instructions");
   }
   for(String[] corruptRecord:new String[][]{{"bad",""},{"87","/invalid"},{"87",dir},{"",dir}}){
    e=fresh();e.context.getSharedPreferences("run",0).edit().putString("boot",corruptRecord[0]).putString("dir",corruptRecord[1]).commit();run(e,true);check(e.failureKind==FailureText.Kind.REBOOT_REQUIRED&&ShizukuShell.launches==0&&e.message.contains("清除 ANB Root 应用数据"),"malformed run record fails closed even across reboot");
   }
   e=fresh();ShizukuShell.module=true;CountDownLatch displayDone=new CountDownLatch(1);check(e.start(text->{throw new IllegalStateException("display");},displayDone::countDown,false),"observer failure request accepted");check(displayDone.await(8,TimeUnit.SECONDS)&&e.phase==RecoveryEngine.Phase.SUCCESS&&!e.isBusy(),"observer failure cannot abort recovery verification");
   e=fresh();ShizukuShell.blockProbe=true;e.checkEnvironment();check(ShizukuShell.entered.await(3,TimeUnit.SECONDS),"probe entered");check(e.isChecking()&&!e.start(s->{},()->{},true)&&!e.selectAllowShell(true),"checking excludes recovery and options");ShizukuShell.release.countDown();long end=System.nanoTime()+3_000_000_000L;while(e.isBusy()&&System.nanoTime()<end)Thread.sleep(10);check(!e.isBusy(),"probe lease released");
   System.out.println("PASS: production engine with simulated shell: firmware gate, verification-only, boot wait/retry, no duplicate launch, lost-state lock, security failure, directory retention, orphaned loaded module rejection, nonfatal diagnostic storage, retained terminal guidance, authorization state changes, safe preference defaults and persistent run repair instructions, shared exclusion");
  }finally{System.setProperty("os.version",old);}
 }
}